using ProjetoIntegradorBack.Api.Commands; using ProjetoIntegradorBack.Api.Queries; using ProjetoIntegradorBack.Domain.DTOs; using ProjetoIntegradorBack.Domain.Entities; using ProjetoIntegradorBack.Domain.Interfaces; using Prime.Architecture.Mapper.Interfaces; using Prime.Architecture.Mediator.Standard.Requests;
namespace ProjetoIntegradorBack.Api.Handlers.NavalhaCorte;
public class ListEmployeesHandler(IEmployeeRepository r,IMapper m):IRequestHandler<ListEmployeesQuery,List<EmployeeDto>>{public async Task<List<EmployeeDto>> Handle(ListEmployeesQuery q,CancellationToken c){var x=await r.ListPorEstablishmentAsync(q.EstablishmentId,c);return x.IsSuccess?x.Success!.Select(v=>m.Map<Employee,EmployeeDto>(v)).ToList():[];}}
public class CriarEmployeeHandler(IEmployeeRepository r,IMapper m):IRequestHandler<CreateEmployeeCommand,EmployeeDto>{public async Task<EmployeeDto> Handle(CreateEmployeeCommand q,CancellationToken c){var x=await r.AddAsync(new Employee{EstablishmentId=q.EstablishmentId,UserId=q.UserId,Name=q.Name,Email=q.Email,Phone=q.Phone,Role=q.Role,CommissionPercentage=q.CommissionPercentage,IsActive=true},c);if(x.IsFailure)throw new InvalidOperationException();return m.Map<Employee,EmployeeDto>(x.Success!);}}
